    fun minDifference(nums:IntArray,queries:Array<IntArray>):IntArray{
        val prefix=Array(nums.size+1){
            IntArray(101)
        };
        for(i in nums.indices){
            prefix[i].copyInto(prefix[i+1]);
            prefix[i+1][nums[i]]++
        };
        return IntArray(queries.size){
